{
  "goal": "Analyze quarterly sales CSV files: detect issues, repair, revalidate, compute stats, merge, review, generate consolidated Markdown report.",
  "steps": [
    {
      "name": "foreach_quarter",
      "kind": "foreach",
      "over": "inputs",
      "description": "Process each quarterly sales CSV file",
      "body": [
        {
          "name": "inspect_schema",
          "kind": "primitive",
          "capability": "csv.inspect_schema",
          "code": "{\"path\": \"${item}\"}",
          "output": {
            "name": "schema_report",
            "typeName": "String"
          }
        },
        {
          "name": "detect_issues",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "import pandas as pd\nimport json\ndf = pd.read_csv('${item}')\nissues = {}\nissues['missing'] = df.isnull().sum().to_dict()\nissues['duplicates'] = int(df.duplicated().sum())\nnumeric_cols = df.select_dtypes(include='number').columns\noutliers = {}\nfor col in numeric_cols:\n    mean = df[col].mean()\n    std = df[col].std()\n    outliers[col] = int(df[(df[col] > mean + 3*std) | (df[col] < mean - 3*std)].shape[0])\nissues['outliers'] = outliers\nissues['type_errors'] = []\nissues['columns'] = list(df.columns)\nenv['issues_json'] = json.dumps(issues)",
          "inputBindings": [
            { "param": "item", "source": "foreach_quarter", "binding": "item" }
          ],
          "output": {
            "name": "issues_json",
            "typeName": "String"
          }
        },
        {
          "name": "repair",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "import pandas as pd\nimport json\nfrom io import StringIO\ndf = pd.read_csv('${item}')\nissues = json.loads('${issues_json}')\ndf = df.drop_duplicates()\nfor col in df.columns:\n    if df[col].dtype in ['int64', 'float64']:\n        df[col].fillna(df[col].median(), inplace=True)\n    else:\n        df[col].fillna(df[col].mode()[0] if not df[col].mode().empty else '', inplace=True)\nenv['repaired_csv'] = df.to_csv(index=False)",
          "inputBindings": [
            { "param": "item", "source": "foreach_quarter", "binding": "item" },
            { "param": "issues_json", "source": "detect_issues", "binding": "issues_json" }
          ],
          "output": {
            "name": "repaired_csv",
            "typeName": "String"
          }
        },
        {
          "name": "revalidate",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "import pandas as pd\nimport json\nfrom io import StringIO\ndf = pd.read_csv(StringIO('${repaired_csv}'))\nvalidation = {}\nvalidation['missing'] = int(df.isnull().sum().sum())\nvalidation['duplicates'] = int(df.duplicated().sum())\nvalidation['valid'] = validation['missing'] == 0 and validation['duplicates'] == 0\nenv['validation_report'] = json.dumps(validation)",
          "inputBindings": [
            { "param": "repaired_csv", "source": "repair", "binding": "repaired_csv" }
          ],
          "output": {
            "name": "validation_report",
            "typeName": "String"
          }
        },
        {
          "name": "compute_stats",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "import pandas as pd\nimport json\nfrom io import StringIO\ndf = pd.read_csv(StringIO('${repaired_csv}'))\nstats = {}\nstats['row_count'] = int(len(df))\nstats['columns'] = {}\nfor col in df.select_dtypes(include='number').columns:\n    stats['columns'][col] = {\n        'sum': float(df[col].sum()),\n        'mean': float(df[col].mean()),\n        'std': float(df[col].std()),\n        'min': float(df[col].min()),\n        'max': float(df[col].max())\n    }\nenv['quarter_stats'] = json.dumps(stats)",
          "inputBindings": [
            { "param": "repaired_csv", "source": "repair", "binding": "repaired_csv" }
          ],
          "output": {
            "name": "quarter_stats",
            "typeName": "String"
          }
        },
        {
          "name": "per_file_record",
          "kind": "primitive",
          "capability": "execute_python",
          "code": "import json\nrecord = {\n    'file': '${item}',\n    'schema_report': json.loads('${schema_report}'),\n    'issues': json.loads('${issues_json}'),\n    'validation': json.loads('${validation_report}'),\n    'stats': json.loads('${quarter_stats}')\n}\nenv['per_file_record'] = json.dumps(record)",
          "inputBindings": [
            { "param": "item", "source": "foreach_quarter", "binding": "item" },
            { "param": "schema_report", "source": "inspect_schema", "binding": "schema_report" },
            { "param": "issues_json", "source": "detect_issues", "binding": "issues_json" },
            { "param": "validation_report", "source": "revalidate", "binding": "validation_report" },
            { "param": "quarter_stats", "source": "compute_stats", "binding": "quarter_stats" }
          ],
          "output": {
            "name": "per_file_record",
            "typeName": "String"
          }
        }
      ],
      "output": {
        "name": "all_records",
        "typeName": "List<String>"
      }
    },
    {
      "name": "merge_results",
      "kind": "primitive",
      "capability": "execute_python",
      "code": "import json\nrecords = [json.loads(r) for r in json.loads('${all_records}')]\nmerged = {}\nmerged['quarterly_files'] = records\nall_stats = []\nfor rec in records:\n    all_stats.append(rec['stats'])\nmerged['overall_stats'] = all_stats\nmerged['all_issues'] = [rec['issues'] for rec in records]\nmerged['validation_summary'] = [rec['validation'] for rec in records]\nenv['merged_json'] = json.dumps(merged)",
      "inputBindings": [
        { "param": "all_records", "source": "foreach_quarter", "binding": "all_records" }
      ],
      "output": {
        "name": "merged_json",
        "typeName": "String"
      }
    },
    {
      "name": "quality_review",
      "kind": "primitive",
      "capability": "execute_python",
      "code": "import json\nmerged = json.loads('${merged_json}')\nreview = \"Quality Review\\n\"\nreview += \"=\" * 50 + \"\\n\"\nfor rec in merged['quarterly_files']:\n    review += f\"\\nFile: {rec['file']}\\n\"\n    review += f\"  Issues: missing={rec['issues'].get('missing', {})}, duplicates={rec['issues'].get('duplicates', 0)}, outliers={rec['issues'].get('outliers', {})}\\n\"\n    review += f\"  Validation: valid={rec['validation'].get('valid', False)}\\n\"\nreview += \"\\nOverall: All files processed.\"\nenv['quality_review_text'] = review",
      "inputBindings": [
        { "param": "merged_json", "source": "merge_results", "binding": "merged_json" }
      ],
      "output": {
        "name": "quality_review_text",
        "typeName": "String"
      }
    },
    {
      "name": "generate_report",
      "kind": "primitive",
      "capability": "execute_python",
      "code": "import json\nmerged = json.loads('${merged_json}')\nreview = '${quality_review_text}'\nmd = \"# Consolidated Quarterly Sales Report\\n\\n\"\nmd += \"## Evidence Log\\n\\n\"\nmd += \"| File | Issues | Repaired | Validated | Stats |\\n\"\nmd += \"|------|--------|----------|-----------|-------|\\n\"\nfor rec in merged['quarterly_files']:\n    file_name = rec['file'].split('/')[-1]\n    issues = rec['issues']\n    valid = rec['validation'].get('valid', False)\n    stats = rec['stats']\n    md += f\"| {file_name} | {json.dumps(issues)} | Repaired | {valid} | {json.dumps(stats)} |\\n\"\nmd += \"\\n## Quality Review\\n\\n\"\nmd += review\nmd += \"\\n\\n## Merged Statistics\\n\\n\"\nmd += json.dumps(merged['overall_stats'], indent=2)\nenv['report_md'] = md",
      "inputBindings": [
        { "param": "merged_json", "source": "merge_results", "binding": "merged_json" },
        { "param": "quality_review_text", "source": "quality_review", "binding": "quality_review_text" }
      ],
      "output": {
        "name": "report_md",
        "typeName": "String"
      }
    }
  ],
  "dataFlow": [
    { "fromStep": "inspect_schema", "toStep": "per_file_record", "binding": "schema_report" },
    { "fromStep": "detect_issues", "toStep": "repair", "binding": "issues_json" },
    { "fromStep": "detect_issues", "toStep": "per_file_record", "binding": "issues_json" },
    { "fromStep": "repair", "toStep": "revalidate", "binding": "repaired_csv" },
    { "fromStep": "repair", "toStep": "compute_stats", "binding": "repaired_csv" },
    { "fromStep": "revalidate", "toStep": "per_file_record", "binding": "validation_report" },
    { "fromStep": "compute_stats", "toStep": "per_file_record", "binding": "quarter_stats" },
    { "fromStep": "foreach_quarter", "toStep": "merge_results", "binding": "all_records" },
    { "fromStep": "merge_results", "toStep": "quality_review", "binding": "merged_json" },
    { "fromStep": "merge_results", "toStep": "generate_report", "binding": "merged_json" },
    { "fromStep": "quality_review", "toStep": "generate_report", "binding": "quality_review_text" }
  ],
  "controlFlow": [
    { "step": "foreach_quarter", "kind": "foreach", "over": "inputs" }
  ]
}

